    static readonly Dictionary<string, Texture2D> cache = new Dictionary<string, Texture2D>();

    public static Texture2D Get(string name)
    {
        Texture2D tex;
        if(cache.TryGetValue(name, out tex) && tex != null) return tex;
        string mask;
        if(!Masks.TryGetValue(name, out mask)) return null;
        tex = new Texture2D(Size, Size, TextureFormat.RGBA32, false);
        tex.hideFlags = HideFlags.HideAndDontSave;
        tex.filterMode = FilterMode.Point;
        tex.wrapMode = TextureWrapMode.Clamp;
        var pixels = new Color32[Size * Size];
        for(var y = 0; y < Size; y++)
        {
            for(var x = 0; x < Size; x++)
            {
                var ch = mask[y * Size + x];
                byte a = ch == '#' ? (byte)255 : ch == '+' ? (byte)110 : (byte)0;
                pixels[(Size - 1 - y) * Size + x] = new Color32(255, 255, 255, a);
            }
        }
        tex.SetPixels32(pixels);
        tex.Apply(false);
        cache[name] = tex;
        return tex;
    }
